import { resolve } from "node:path";
import { defineConfig, type Connect, type Plugin } from "vite";
import { isWorkPath } from "./src/shared/routing/client-route";

/**
 * Vite config for the MASRA site.
 *
 * Fully static: two HTML entries + TS modules + pre-optimized images in
 * /public/images (generated by scripts/optimize-images.mjs, never processed
 * by Vite). Build output (dist/) deploys to Cloudflare Pages.
 *
 * v3 adds the client-page entry (work.html). In production Cloudflare
 * rewrites /work/* → /work (public/_redirects; the extensionless target
 * resolves to work.html — "/work.html" would 308 to "/work"). The plugin below does
 * the same for `vite dev` and `vite preview`, so deep links and refreshes
 * on /work/<id> behave identically everywhere (tested rule: isWorkPath;
 * the page itself then validates the id with parseClientRoute).
 */

/** Rewrite client-page URLs to the work.html entry (dev + preview). */
function clientRouteRewrite(): Plugin {
  const rewrite: Connect.NextHandleFunction = (req, _res, next) => {
    // Every /work/* request is rewritten, like Cloudflare's rule. No module
    // or asset lives under /work/ (all are root-absolute), so this is safe.
    const url = new URL(req.url ?? "/", "http://localhost");
    if (isWorkPath(url.pathname)) req.url = "/work.html" + url.search;
    next();
  };
  return {
    name: "masra-client-route-rewrite",
    configureServer(server) {
      server.middlewares.use(rewrite);
    },
    configurePreviewServer(server) {
      server.middlewares.use(rewrite);
    },
  };
}

export default defineConfig({
  plugins: [clientRouteRewrite()],
  build: {
    // Keep asset filenames hashed (default) so public/_headers can cache
    // /assets/* as immutable on Cloudflare Pages.
    target: "es2022",
    rollupOptions: {
      input: {
        main: resolve(__dirname, "index.html"),
        work: resolve(__dirname, "work.html"),
      },
    },
  },
  server: {
    port: 5173,
    strictPort: true,
  },
});
